func longestCommonSubsequence(text1 string, text2 string) int {
	M, N := len(text1), len(text2)
	dp := make([][]int, M+1)
	for i := range dp {
		dp[i] = make([]int, N+1)
	}
	for i := 1; i <= M; i++ {
		for j := 1; j <= N; j++ {
			if text1[i-1] == text2[j-1] {
				dp[i][j] = dp[i-1][j-1] + 1
			} else {
				if dp[i-1][j] > dp[i][j-1] {
					dp[i][j] = dp[i-1][j]
				} else {
					dp[i][j] = dp[i][j-1]
				}
			}
		}
	}
	return dp[M][N]
}

// 躲坑：Go 中 make([][]int, M) 只是创建了 M 个 nil 行，
