func longestCommonSubsequence(str1 string, str2 string) int {
	m, n := len(str1), len(str2)
	// 构建 DP table 和 base case
	dp := make([][]int, m+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}
	// 进行状态转移
	for i := 1; i <= m; i++ {
		for j := 1; j <= n; j++ {
			if str1[i-1] == str2[j-1] {
				// 找到一个 lcs 中的字符
				dp[i][j] = 1 + dp[i-1][j-1]
			} else {
				// dp[i][j] = max(dp[i-1][j], dp[i][j-1])
				if dp[i-1][j] > dp[i][j-1] {
					dp[i][j] = dp[i-1][j]
				} else {
					dp[i][j] = dp[i][j-1]
				}
			}
		}
	}
	return dp[m][n]
}

